use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode};
use crate::params::Params;
use crate::types::{AttributeUpdate, GroupId, QueueName, Seconds, deduplication_id};

#[derive(Debug)]
pub enum Command<'a> {
    CreateQueue {
        name: QueueName,
        attributes: AttributeUpdate<'a>,
    },
