                let queue = params.required_string("QueueName")?;
                Ok(Self::ReceiveMessage {
                    queue,
                    max_messages: params.integer("MaxMessages", 1..=10)?.unwrap_or(1),
                    visibility_timeout: params.seconds("VisibilityTimeout", 0..=43_200)?,
                })
