    pub fn purge(&mut self) {
        self.messages.clear();
        self.ready.clear();
        self.held.clear();
        self.groups.clear();
        self.handles.clear();
    }

    pub fn counts(&self) -> Counts {
        let in_flight = self
            .held
            .iter()
            .filter(|(_, arrival)| matches!(self.messages[arrival].hold, Hold::InFlight { .. }))
            .count();
