    }

    /// Resolves a receipt handle of `queue_name` to the in-flight message it
    /// belongs to.
    fn claim(
        &mut self,
        queue_name: &str,
        receipt_handle: &str,
    ) -> Result<(&mut Queue, ReceiptHandle, Arrival), Error> {
