fn dead_letter_move_resets_the_message_and_ignores_the_group_it_left() {
    let responses = run(&[
        create("dead", json!({})),
        create("main", json!({"DeadLetterQueue": "dead", "MaxReceiveCount": 1})),
        send("main", "poison"),
        json!({"Command": "ReceiveMessage", "QueueName": "main", "VisibilityTimeout": 0}),
        receive("main"),
        counts("main"),
        json!({"Command": "ReceiveMessage", "QueueName": "dead"}),
